async function releaseCenter(){const existing=await all('releases'),state=Object.fromEntries(existing.map(x=>[x.id,x]));const b=layer('Release & Discover','Build → Test → Secure → Deploy → Discover → Prove','<section class="v23-section"><p class="v23-section-title">Checklist de livraison</p><div class="v23-group" id="rel23"></div></section><p class="v23-muted">Search Console et les comptes externes ne sont jamais marqués comme vérifiés sans action réelle de ta part.</p>');const root=$('#rel23',b);for(const [id,title,desc] of releaseChecks){const row=document.createElement('button');row.className='v23-row';const status=state[id]?.status||'todo';row.innerHTML='<strong>'+(status==='done'?'✓ ':'')+esc(title)+'</strong><small>'+esc(desc)+'</small>';row.onclick=async()=>{await put('releases',{id,title,status:status==='done'?'todo':'done',updatedAt:new Date().toISOString()});releaseCenter()};root.append(row)}}
function validBriefing(d){return !!(d&&d.version===1&&typeof d.generatedAt==='string'&&Number.isFinite(Date.parse(d.generatedAt))&&Array.isArray(d.items)&&d.items.length>0&&d.items.length<=50&&d.items.every(x=>x&&['title','category','source','date','summary','url'].every(k=>typeof x[k]==='string'&&x[k].trim().length>0&&x[k].length<= (k==='summary'?6000:2048))&&/^https:\/\//i.test(x.url)&&/^\d{4}-\d{2}-\d{2}$/.test(x.date)))}
async function dailyBriefing(b){const root=$('#daily-feed',b);if(!root)return;let data;try{data=(await all('meta')).find(x=>x.id==='daily-briefing')?.data}catch{}let fresh=false;try{const res=await fetch('./daily-briefing.json',{cache:'no-store'});if(!res.ok)throw Error('HTTP');const raw=await res.text();if(raw.length>250000)throw Error('size');const d=JSON.parse(raw);if(!validBriefing(d))throw Error('schema');if(data?.generatedAt&&Date.parse(d.generatedAt)<Date.parse(data.generatedAt))throw Error('older edition');await put('meta',{id:'daily-briefing',data:d});data=d;fresh=true}catch{}root.replaceChildren();const status=document.createElement('p');status.className='v23-note';status.textContent=data?.generatedAt?'Édition du '+new Date(data.generatedAt).toLocaleString('fr-FR')+' · '+(fresh?'Synchronisée':'Copie locale'):'Première édition en attente';root.append(status);if(!data?.items?.length)return;let seen='';try{seen=localStorage.getItem('vekaid-briefing-seen')||''}catch{}if(seen!==data.generatedAt){const n=document.createElement('button');n.className='v23-btn primary';n.textContent='Nouvelle édition · marquer comme lue';n.onclick=()=>{try{localStorage.setItem('vekaid-briefing-seen',data.generatedAt)}catch{}n.remove()};root.append(n)}for(const item of data.items){if(!item||typeof item.title!=='string')continue;const row=document.createElement('article');row.className='v23-group';const h=document.createElement('div');h.className='v23-row';const title=document.createElement('strong');title.textContent=item.title;const meta=document.createElement('small');meta.textContent=[item.category,item.source,item.date].filter(Boolean).join(' · ');h.append(title,meta);row.append(h);const p=document.createElement('p');p.className='v23-note';p.textContent=String(item.summary||'');row.append(p);try{const u=new URL(item.url);if(u.protocol==='https:'){const a=document.createElement('a');a.className='v23-btn';a.href=u.href;a.target='_blank';a.rel='noopener noreferrer';a.textContent='Lire la source';row.append(a)}}catch{}root.append(row)}}
function intel(){const b=layer('Intel','Accès aux modules d’intelligence existants','<section class="v23-section"><p class="v23-section-title">Daily Briefing · Actualités mondiales</p><div id="daily-feed" aria-live="polite">Chargement…</div></section><section class="v23-section"><p class="v23-section-title">Sources et systèmes</p><div class="v23-group"><button class="v23-row" data-x="claude"><strong>Claude</strong><small>Sessions observées</small></button><button class="v23-row" data-x="agents"><strong>Agents</strong><small>Rôles et orchestration</small></button><button class="v23-row" data-x="security"><strong>Sécurité</strong><small>Diagnostic et contrôles</small></button><button class="v23-row" data-x="github"><strong>GitHub</strong><small>État du dépôt</small></button></div></section>');dailyBriefing(b);b.querySelectorAll('[data-x]').forEach(x=>x.onclick=()=>{b.closest('.v23-layer').remove();window.tab?.(x.dataset.x)})}
async function you(){const t=await tickets(),s=await all('skills'),reg=await navigator.serviceWorker?.getRegistration?.('./').catch(()=>null),standalone=matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;const b=layer('You','Santé de l’application, données locales et continuité',`<div class="v23-grid"><article class="v23-card"><span class="v23-k">VERSION</span><b>V${V}</b><small>Stockage local</small></article><article class="v23-card"><span class="v23-k">PWA</span><b>${standalone?'Installée':'Navigateur'}</b><small>Service worker : ${reg?'actif':'à vérifier'}</small></article><article class="v23-card"><span class="v23-k">DONNÉES</span><b>${t.length} missions</b><small>${s.length} preuves</small></article><article class="v23-card"><span class="v23-k">RÉSEAU</span><b>${navigator.onLine?'En ligne':'Hors ligne'}</b><small>cache PWA disponible</small></article><article class="v23-card wide"><div class="v23-actions"><button class="v23-btn primary" id="exp23">Exporter backup</button><button class="v23-btn" id="pal23">Command Palette</button></div></article></div><section class="v23-privacy"><h3>Confidentialité & données</h3><p>VEKAID n’a actuellement aucun compte utilisateur ni connexion sociale. Les données V23 restent dans le stockage local de ce navigateur tant que tu ne les exportes pas toi-même.</p><div class="v23-privacy-grid"><div class="v23-privacy-item"><strong>Aucun login artificiel</strong><small>Apple/Google ne seront ajoutés que si un vrai système de comptes devient nécessaire.</small></div><div class="v23-privacy-item"><strong>Aucun secret dans le frontend</strong><small>Clés API, mots de passe et tokens ne doivent jamais être enregistrés dans l’app publique.</small></div></div></section>`);languagePicker(b);$('#exp23',b).onclick=backup;$('#pal23',b).onclick=palette}
function snapshot(){return new Promise((resolve,reject)=>{const names=['meta','tickets','skills','releases'],tx=db.transaction(names,'readonly'),data={};for(const name of names){const request=tx.objectStore(name).getAll();request.onsuccess=()=>{data[name]=request.result}}tx.oncomplete=()=>resolve(data);tx.onabort=()=>reject(tx.error||new Error('Lecture annulée'));tx.onerror=()=>reject(tx.error||new Error('Lecture impossible'))})}
async function backup(){try{const data=await snapshot();const legacy={};for(const key of ['vekaid.atlas.v5.offline','vekaid.commanddeck.v4.offline','vekaid.intel.v1']){legacy[key]=localStorage.getItem(key)}const payload={format:'vekaid.backup.v23',version:V,schemaVersion:2,at:new Date().toISOString(),tickets:data.tickets,skills:data.skills,releases:data.releases,academy:data.meta.filter(x=>typeof x.id==='string'&&x.id.startsWith('academy:')),meta:data.meta,legacy:{atlas:legacy['vekaid.atlas.v5.offline'],intel:legacy['vekaid.intel.v1'],commanddeck:legacy['vekaid.commanddeck.v4.offline']}};const a=document.createElement('a'),u=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.href=u;a.download='vekaid-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),30000)}catch(e){alert('Sauvegarde impossible. Tes données n’ont pas été modifiées. Réessaie.')}}
function palette(){const b=layer('Search VEKAID','Recherche et commandes locales','<input class="v23-search" id="q23" placeholder="Mission, skill, projet…"><div class="v23-list" id="r23"></div>'),q=$('#q23',b),r=$('#r23',b),cmd=[['Aujourd’hui','today',today],['Nouvelle mission','work',work],['Academy · bibliothèque','learn',academy],['Skills & preuves','learn',learn],['Studio image & média','work',studio],['Release & Discover','work',releaseCenter],['Agents','intel',()=>{b.closest('.v23-layer').remove();window.tab?.('agents')}],['Projets','work',()=>{b.closest('.v23-layer').remove();window.tab?.('projects')}],['Sécurité','intel',()=>{b.closest('.v23-layer').remove();window.tab?.('security')}]];const draw=()=>{const v=q.value.toLowerCase();r.innerHTML='';cmd.filter(x=>x[0].toLowerCase().includes(v)||x[1].includes(v)).forEach(x=>{const z=document.createElement('button');z.className='v23-row';z.innerHTML='<strong>'+x[0]+'</strong><small>'+x[1]+'</small>';z.onclick=x[2];r.append(z)})};q.oninput=draw;draw();q.focus()}
let vekaidLaunchLast=0,vekaidHiddenAt=0;
function buildLaunchIdent(){
  document.getElementById('vekaidLaunch')?.remove();
  const el=document.createElement('div');
  el.id='vekaidLaunch';el.className='vekaid-launch';el.setAttribute('aria-hidden','true');
  el.innerHTML='<div class="vekaid-launch__stage"><div class="vekaid-launch__radar"><div class="vekaid-launch__ring"></div><div class="vekaid-launch__ring r2"></div><div class="vekaid-launch__sweep"></div></div><div class="vekaid-launch__halo"></div><svg class="vekaid-launch__v" viewBox="0 0 160 160" aria-hidden="true"><path class="left" d="M34 34 L80 128"></path><path class="right" d="M126 34 L80 128"></path></svg><div class="vekaid-launch__brand">VEKAID</div></div>';
  document.body.append(el);
  return el;
}
function playLaunchIdent(force=false,reuseExisting=false){
  const now=Date.now();
  if(!force && now-vekaidLaunchLast<900)return;
  vekaidLaunchLast=now;
  const reduce=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
  let el=reuseExisting?document.getElementById('vekaidLaunch'):null;
  if(!el){document.body.classList.remove('vekaid-ready');document.body.classList.add('vekaid-entering');el=buildLaunchIdent();}
  requestAnimationFrame(()=>requestAnimationFrame(()=>{
    setTimeout(()=>{document.body.classList.remove('vekaid-entering');document.body.classList.add('vekaid-ready');requestAnimationFrame(()=>el.classList.add('is-done'));setTimeout(()=>el.remove(),reduce?180:820)},reduce?120:1260);
  }));
}
function installLaunchLifecycle(){
  playLaunchIdent(true,true);
  document.addEventListener('visibilitychange',()=>{
    if(document.hidden){vekaidHiddenAt=Date.now();return;}
    if(Date.now()-vekaidHiddenAt>500)playLaunchIdent(true,false);
  });
  window.addEventListener('pageshow',e=>{if(e.persisted)playLaunchIdent(true,false)});
}
